def evaluate(current_reputation, observation, my_history, round_num):
    # Decay: more weight on recent observations
    decay = 0.8

    # Compute own donation rate over last 6 actions
    recent_window = 6
    recent = [h for h in my_history[-recent_window:]] if len(my_history) >= recent_window else my_history
    if recent:
        own_donation_rate = sum(1 for h in recent if h["action"] == "donate") / len(recent)
    else:
        own_donation_rate = 0.5  # neutral start

    # Update magnitudes depend on own generosity: generous agents are more tolerant
    if own_donation_rate > 0.5:
        pos_update = 0.35
        neg_update = -0.20
    else:
        pos_update = 0.20
        neg_update = -0.45

    if observation["action"] == "donate":
        new_rep = decay * current_reputation + pos_update
    else:
        new_rep = decay * current_reputation + neg_update

    # Clamp to allowed range
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    # Compute own recent donation rate for indirect bias
    recent_window = 6
    recent = [h for h in my_history[-recent_window:]] if len(my_history) >= recent_window else my_history
    if recent:
        donation_rate = sum(1 for h in recent if h["action"] == "donate") / len(recent)
    else:
        donation_rate = 0.5

    # Base threshold: higher generosity -> lower threshold
    base_threshold = 0.55 - 0.35 * donation_rate  # ranges from 0.2 to 0.55

    # Extremes: always donate to very high reputation, never to very low
    if recipient_reputation > 0.85:
        return True
    if recipient_reputation < -0.4:
        return False

    # Gradual increase in generosity over rounds (slowly reduce threshold)
    base_threshold -= round_num * 0.0015
    base_threshold = max(0.1, min(0.75, base_threshold))

    return recipient_reputation > base_threshold
